def solve_octagon_prob(vertices):
    # Function to check if a triangle is right angled
    def is_right_triangle(a, b, c):
        sides = [a, b, c]
        sides.sort()  # sort the sides in ascending order
        return math.isclose(sides[0]**2 + sides[1]**2, sides[2]**2)

    # Function to check if a triangle is an arithmetic progression
    def is_arithmetic_progression(a, b, c):
        return all([(b-a) == (c-b), (b-a) > 0])

    total = 0  # count of right angled AP triangles
    for triangle in combinations(vertices, 3):
