def calculate_grouped_std(intervals: List[Tuple[int, int]], frequencies: List[int]) -> float:
    if len(intervals) != len(frequencies):
        raise ValueError("Intervals and Frequencies must have the same length")

    mean = sum([(interval[0] + interval[1]) / 2 * freq for interval, freq in zip(intervals, frequencies)]) / sum(frequencies)

    variance = sum([((interval[0] + interval[1]) / 2 - mean) ** 2 * freq for interval, freq in zip(intervals, frequencies)]) / (sum(frequencies)-1)

