def calculate_p(total_slots: int, total_books: int) -> float:
    dp = [[0] * (total_slots + 1) for _ in range(total_books + 1)]

    # Base case when there are no books or slots. 
    dp[0][0] = 1

    for i in range(1, total_books + 1):
        for j in range(1, total_slots + 1):
            if j > i:
